def evaluate(current_reputation, observation, my_history, round_num):
    # Determine base update from observed action
    if observation['action'] == 'cooperate':
        base = 1.0
    else:
        base = -1.0

    # Compute own cooperation rate from history (excluding current round)
    own_coop = 0
    total = len(my_history)
    if total > 0:
        for h in my_history:
            # Each entry is a dict with 'action' key for our own action
            if h['action'] == 'cooperate':
                own_coop += 1
        own_coop_rate = own_coop / total
    else:
        own_coop_rate = 0.5  # neutral if no history

    # Modify update based on own cooperative behaviour:
    # If we have been cooperative (>70%), amplify positive updates and reduce penalties (forgiveness).
    # If we have been defecting often (>70%), do the opposite (more sceptical).
    if own_coop_rate > 0.7:
        if base > 0:
            base = min(1.0, base * 1.2)
        else:
            base = max(-1.0, base * 0.8)  # be more forgiving
    elif own_coop_rate < 0.3:
        if base < 0:
            base = max(-1.0, base * 1.2)
        else:
            base = min(1.0, base * 0.8)  # reward less

    # Exponential moving average to give more weight to recent observations
    alpha = 0.3  # higher alpha = faster adaptation to recent
    new_reputation = (1 - alpha) * current_reputation + alpha * base
    # Ensure within [-1, 1]
    return max(-1.0, min(1.0, new_reputation))


def decide(recipient_reputation, round_num, my_history):
    # Count our own defections so far
    own_defections = 0
    for h in my_history:
        if h['action'] == 'defect':
            own_defections += 1

    # Initial unconditional cooperation for first 2 rounds
    if round_num <= 2:
        return True

    # For rounds 3-6, be more lenient
    if round_num <= 6:
        threshold = -0.2
    else:
        # Later rounds: become stricter, especially if we have defected often ourselves
        threshold = 0.2 + 0.15 * own_defections
        threshold = min(threshold, 0.8)  # cap to avoid being too extreme

    return recipient_reputation > threshold
